use std::env;
use std::error::Error;
use std::fs;
use std::process::ExitCode;
use std::sync::mpsc;

use wgpu::util::DeviceExt;

const WORKGROUP_SIZE: u32 = 64;

// Two kernels per step. `accelerate` reads only positions and writes
// accelerations; `integrate` then updates velocities and positions. Each
// kernel runs in its own compute pass, so the second sees every acceleration
// and position written by the first, and the accelerations of a step are all
// computed from the positions the step started with.
const SHADER: &str = r#"
struct Params {
    count: u32,
    dt: f32,
    pad0: u32,
    pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.count; j = j + 1u) {
        // j == i contributes exactly zero: d is zero there.
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    count: u32,
    dt: f32,
    _pad: [u32; 2],
}

struct Input {
    steps: usize,
    dt: f32,
    particles: Vec<[f32; 4]>,
}

fn read_input(path: &str) -> Result<Input, Box<dyn Error>> {
    let text = fs::read_to_string(path)?;
    let mut tokens = text.split_whitespace();
    let mut next = || tokens.next().ok_or("input file ended early");

    let count: usize = next()?.parse()?;
    let steps: usize = next()?.parse()?;
    let dt: f32 = next()?.parse()?;
    if count == 0 {
        return Err("count must be at least 1".into());
    }

    let mut particles = Vec::with_capacity(count);
    for _ in 0..count {
        let mut field = || -> Result<f32, Box<dyn Error>> {
            Ok(next()?.parse()?)
        };
        particles.push([field()?, field()?, field()?, field()?]);
    }
    Ok(Input { steps, dt, particles })
}

async fn simulate(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), Box<dyn Error>> {
    let n = input.particles.len();
    let count = u32::try_from(n)?;

    let instance = wgpu::Instance::default();
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await?;
    let (device, queue) = adapter.request_device(&wgpu::DeviceDescriptor::default()).await?;

    let pos_init: Vec<[f32; 2]> = input.particles.iter().map(|p| [p[0], p[1]]).collect();
    let vel_init: Vec<[f32; 2]> = input.particles.iter().map(|p| [p[2], p[3]]).collect();
    let vec_bytes = (n * std::mem::size_of::<[f32; 2]>()) as u64;

    let params = Params {
        count,
        dt: input.dt,
        _pad: [0; 2],
    };
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("pos"),
        contents: bytemuck::cast_slice(&pos_init),
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("vel"),
        contents: bytemuck::cast_slice(&vel_init),
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("acc"),
        size: vec_bytes,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let pos_read = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("pos readback"),
        size: vec_bytes,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let vel_read = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("vel readback"),
        size: vec_bytes,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let storage_entry = |binding: u32| wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only: false },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    };
    let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("particles"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            storage_entry(1),
            storage_entry(2),
            storage_entry(3),
        ],
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("particles"),
        layout: &bind_group_layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: pos_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: vel_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: acc_buf.as_entire_binding(),
            },
        ],
    });

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("particles"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("particles"),
        bind_group_layouts: &[&bind_group_layout],
        push_constant_ranges: &[],
    });
    let make_pipeline = |entry_point: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry_point),
            layout: Some(&pipeline_layout),
            module: &shader,
            entry_point: Some(entry_point),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = make_pipeline("accelerate");
    let integrate = make_pipeline("integrate");

    let groups = count.div_ceil(WORKGROUP_SIZE);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("steps"),
    });
    for _ in 0..input.steps {
        {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("accelerate"),
                timestamp_writes: None,
            });
            pass.set_pipeline(&accelerate);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
        {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("integrate"),
                timestamp_writes: None,
            });
            pass.set_pipeline(&integrate);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &pos_read, 0, vec_bytes);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &vel_read, 0, vec_bytes);
    queue.submit(Some(encoder.finish()));

    let pos_slice = pos_read.slice(..);
    let vel_slice = vel_read.slice(..);
    let (pos_tx, pos_rx) = mpsc::channel();
    let (vel_tx, vel_rx) = mpsc::channel();
    pos_slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = pos_tx.send(r);
    });
    vel_slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = vel_tx.send(r);
    });
    device.poll(wgpu::PollType::Wait {
        submission_index: None,
        timeout: None,
    })?;
    pos_rx.recv()??;
    vel_rx.recv()??;

    let pos_out: Vec<[f32; 2]> = bytemuck::cast_slice(&pos_slice.get_mapped_range()).to_vec();
    let vel_out: Vec<[f32; 2]> = bytemuck::cast_slice(&vel_slice.get_mapped_range()).to_vec();
    pos_read.unmap();
    vel_read.unmap();
    Ok((pos_out, vel_out))
}

fn show(value: f64) -> String {
    let text = format!("{value:.6}");
    if text == "-0.000000" {
        "0.000000".to_string()
    } else {
        text
    }
}

fn run() -> Result<(), Box<dyn Error>> {
    let path = env::args()
        .nth(1)
        .ok_or("usage: particles <input-file>")?;
    let input = read_input(&path)?;
    let (pos, vel) = pollster::block_on(simulate(&input))?;

    let n = pos.len() as f64;
    let (mut sx, mut sy) = (0.0f64, 0.0f64);
    let (mut px, mut py) = (0.0f64, 0.0f64);
    let mut kinetic = 0.0f64;
    for (p, v) in pos.iter().zip(&vel) {
        sx += f64::from(p[0]);
        sy += f64::from(p[1]);
        px += f64::from(v[0]);
        py += f64::from(v[1]);
        kinetic += (f64::from(v[0]) * f64::from(v[0]) + f64::from(v[1]) * f64::from(v[1])) / 2.0;
    }
    let (cx, cy) = (sx / n, sy / n);
    let mut squared = 0.0f64;
    for p in &pos {
        let dx = f64::from(p[0]) - cx;
        let dy = f64::from(p[1]) - cy;
        squared += dx * dx + dy * dy;
    }
    let spread = (squared / n).sqrt();

    println!("CENTER {} {}", show(cx), show(cy));
    println!("MOMENTUM {} {}", show(px), show(py));
    println!("KINETIC {}", show(kinetic));
    println!("SPREAD {}", show(spread));
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("error: {err}");
            ExitCode::FAILURE
        }
    }
}

